#define _POSIX_C_SOURCE 200809L
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <xmmintrin.h>
#include "onda_processor_abi.h"
static double now(void) { struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t); return t.tv_sec + t.tv_nsec * 1e-9; }
int main(void) {
  _mm_setcsr(_mm_getcsr() | (1u<<15) | (1u<<6));
  _Alignas(64) float source[128], out[128];
  const void *inputs[] = {source}; void *outputs[] = {out};
  double max_error=0; unsigned max_ulp=0;
  for (int k=0;k<1024;k++) {
    for (int i=0;i<128;i++) source[i]=-100.0f+200.0f*(float)(k*128+i)/131071.0f;
    if (onda_process(NULL,NULL,inputs,outputs,0,128,3,NULL,NULL,NULL,NULL,NULL)) return 1;
    for (int i=0;i<128;i++) {
      float expected=exp2f(source[i]); double rel=fabs((double)out[i]-expected)/expected;
      if(rel>max_error)max_error=rel;
      uint32_t a,b;memcpy(&a,&out[i],4);memcpy(&b,&expected,4);unsigned ulp=a>b?a-b:b-a;
      if(ulp>max_ulp)max_ulp=ulp;
    }
  }
  for(int i=0;i<128;i++)source[i]=-6.0f+12.0f*(float)i/127.0f;
  for(int i=0;i<1000;i++) if(onda_process(NULL,NULL,inputs,outputs,0,128,3,NULL,NULL,NULL,NULL,NULL))return 2;
  printf("{\"max_relative_error\":%.12g,\"max_ulp\":%u,\"rounds_ns_per_frame\":[",max_error,max_ulp);
  for(int round=0;round<7;round++) {
    const int iterations=200000; double start=now();
    for(int i=0;i<iterations;i++)if(onda_process(NULL,NULL,inputs,outputs,0,128,3,NULL,NULL,NULL,NULL,NULL))return 3;
    double elapsed=(now()-start)*1e9/iterations/128;
    printf("%s%.9f",round?",":"",elapsed);
  }
  printf("]}\n");
  return max_ulp>2;
}

